// Intentional LOCAL/TEST-only fail-closed shape gate.
 // n8n Header Auth must be separately configured in encrypted credentials.
 // Validation does NOT grant tenant authority or persist a durable receipt.
 const item = $input.first()?.json;
 const body = item && typeof item === 'object' ? item.body : null;
 const fields = [
   'event_id', 'event_type', 'tenant_id', 'correlation_id', 'occurred_at',
   'authoritative_subject_reference', 'authoritative_subject_version',
   'delivery_idempotency_key'
 ];
 const keys = body && typeof body === 'object' && !Array.isArray(body)
   ? Object.keys(body).sort() : [];
 const shapeOk = keys.length === fields.length &&
   fields.every(k => keys.includes(k));
 const allowedType = shapeOk &&
   ['acquisition.intake.received','engagement.opened'].includes(body.event_type);
 // No runtime decisions, customer PII, payloads, credentials or raw headers
 // are returned to downstream nodes. Always reply 503 until a separately
 // approved hosted durable receipt and tenant binding are installed.
 return [{json:{code:'RECEIVER_NOT_READY',shape_valid:!!allowedType}}];
